import express from "express";
import { fileURLToPath } from "node:url";
import {
  connectDB,
  getAllPhones,
  findPhonesByBrand,
  findPhonesByMaxPrice,
  getThreeCheapestPhones,
  addPhone,
} from "./database.js";

const app = express();
const PORT = 3000;

app.use(express.json());
app.use(express.static(fileURLToPath(new URL("./public", import.meta.url))));

function sendList(res, data, functionName) {
  if (!Array.isArray(data)) {
    return res.status(500).json({
      error: `${functionName}() did not return a list from the database. Complete it in database.js.`,
    });
  }
  res.json(data);
}

app.get("/api/phones", async (req, res) => {
  try {
    sendList(res, await getAllPhones(), "getAllPhones");
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

app.get("/api/phones/search", async (req, res) => {
  try {
    sendList(res, await findPhonesByBrand(req.query.brand), "findPhonesByBrand");
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

app.get("/api/phones/filter", async (req, res) => {
  const maxPrice = Number(req.query.maxPrice);
  if (Number.isNaN(maxPrice)) {
    return res.status(400).json({ error: "Please enter a number." });
  }
  try {
    sendList(res, await findPhonesByMaxPrice(maxPrice), "findPhonesByMaxPrice");
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

app.get("/api/phones/top", async (req, res) => {
  try {
    sendList(res, await getThreeCheapestPhones(), "getThreeCheapestPhones");
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

app.post("/api/phones", async (req, res) => {
  try {
    const saved = await addPhone(req.body);
    if (!saved) {
      return res.status(500).json({
        error: "addPhone() did not return the saved phone. Complete it in database.js.",
      });
    }
    res.status(201).json(saved);
  } catch (err) {
    res.status(400).json({ error: err.message });
  }
});

try {
  await connectDB();
} catch (err) {
  console.log("Could not connect to MongoDB:", err.message);
}

app.listen(PORT, () => {
  console.log(`Server running at http://localhost:${PORT}`);
});
